/* PASS 644 · the painter, at once for the first change, then at most every 300 ms (900 ms while the Forge starts) */
var paintAt = 0, paintPend = null, paintSoon = function () {
  var fb = document.getElementById('forge-boot'), gap = (fb && !fb.classList.contains('fb-gone')) ? 900 : 300, since = Date.now() - paintAt;
  if (since >= gap && !paintPend) { paintAt = Date.now(); paint(); return; }
  if (!paintPend) paintPend = setTimeout(function () { paintPend = null; paintAt = Date.now(); try { paint(); } catch (e) {} }, Math.max(16, gap - since));
};
/* a change that adds no element (a clock's new words, a count) asks nothing of the painter */
var busy = false, mo = new MutationObserver(function (recs) {
  if (recs && recs.length && !recs.some(function (r) { for (var i = 0; i < r.addedNodes.length; i++) if (r.addedNodes[i].nodeType === 1) return true; return false; })) return;
